window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7f3120f846dbdedb"]={"versions": [{"id": "FIG-7f3120f846dbdedb", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (Blockarchitektur) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung der statischen Dekomposition der AP-Laufzeitumgebung (ARA) und deren Abgrenzung gegenüber Applikationsebene (User Applications), Betriebssystemebene (OSI-Schicht via POSIX) und unterlagerter Ausführungsumgebung (Hardware/VM/Container).</li>\n<li><strong>Systemische Einordnung:</strong> Definiert die logische Struktur eines AP-Knotens gemäß AUTOSAR R21-11 (<code>AUTOSAR_EXP_PlatformDesign</code>). Veranschaulicht das Dualitätsprinzip zwischen <em>Platform Foundation Functional Clusters</em> (bibliotheksbasierte In-Process-APIs) und <em>Platform Service Functional Clusters</em> (serviceorientierte IPC/Netzwerk-Dienste), die für Adaptive Applications (AA) über eine einheitliche C++-API abstrahiert werden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Entitäten (Top-to-Bottom)</p>\n<ul class=\"fig-list\">\n<li><strong>User Applications:</strong></li>\n<li><strong>Adaptive Application (AA):</strong> POSIX-konforme Nutzerprozesse mit eigenem virtuellem Adressraum.</li>\n<li><strong>Non-PF Service (<code>ASW::XYZ</code>, <code>ASW::ABC</code>):</strong> Anwendungsdienste, die über das Service-Interface von <code>ara::com</code> für andere AAs bereitgestellt werden (anwendungsspezifisches Service-Providing).</li>\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong></li>\n</ul>\n<p class=\"fig-p\">Definiert die standardisierte Laufzeitumgebung und stellt die Abstraktionsschicht für AAs dar. Unterteilt in:</p>\n<ol class=\"fig-list\">\n<li><strong>Platform Foundation Functional Clusters (API-orientiert, blau kodiert):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>ara::core</code>: Basistypen, Core-Fehlerbehandlung (<code>ara::core::Result</code>, <code>ara::core::ErrorCode</code>), Speicherallokations- und Initialisierungsmechanismen.</li>\n<li><code>ara::com</code>: Service-Oriented Communication (SOC). Bindet Transportprotokolle an:</li>\n<li>Inter-Process Communication (<em>IPC</em>)</li>\n<li>Signal-basierte Übersetzung (<em>Signal PDU</em>)</li>\n<li><em>SOME/IP</em> (Scalable service-Oriented MiddlewarE over IP)</li>\n<li><em>DDS</em> (Data Distribution Service)</li>\n<li><code>ara::exec</code>: Prozesslebenszyklus, Scheduling-Konfiguration und Deterministic Client Control.</li>\n<li><code>ara::iam</code>: Autorisierung und Zugriffskontrolle auf Schnittstellen und Ressourcen.</li>\n<li><code>ara::crypto</code>: PKI, Schlüsselverwaltung, kryptografische Operationen (Sym/Asym, Hashing).</li>\n<li><code>ara::per</code>: Persistente Datenspeicherung (Key-Value-Storage, File-Storage).</li>\n<li><code>ara::phm</code>: Alive-, Deadline- und Logical-Supervision von AAs.</li>\n<li><code>ara::log</code>: Strukturiertes Logging und Tracing (LT-Protokoll/DLT).</li>\n<li><code>ara::idsm</code>: Erfassung und Weiterleitung von Security-Events an den Intrusion Detection System Manager.</li>\n<li><code>ara::tsync</code>: Hochgenaue Zeitsynchronisation (PTP / IEEE 802.1AS).</li>\n<li><code>ara::diag</code>: Fahrzeugdiagnose über UDS / DoIP (Routing, Service-Handler-Anbindung).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Platform Service Functional Clusters (Service-orientiert, grau kodiert):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>ara::sm service</code>: Zustands- und Funktionsgruppenmanagement (State Management).</li>\n<li><code>ara::ucm service</code>: Update and Config Management (Software-Aktualisierung / OTA).</li>\n<li><code>ara::nm service</code>: Netzwerk-Management (Bus-Schlaf-/Wachzustände).</li>\n<li><strong>Operating System Interface:</strong></li>\n<li>Standardisiertes Subsystem via <strong>POSIX PSE51</strong> (Minimal Realtime System Profile gemäß IEEE 1003.13) sowie <strong>C++ Standard Template Library (STL)</strong>. Kapselt Threading, Mutexes, Semaphoren und Filesystem-Basisaufrufe.</li>\n<li><strong>Unterlagerte Basis:</strong></li>\n<li><code>(Virtual) Machine / Container / Hardware</code>: Abstraktion über Hypervisor-Partitionen, Linux-Namespaces/Container oder Bare-Metal-SoC-Ressourcen.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen- & Strukturbeziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>In-Process-Bindings vs. Inter-Process Services:</strong></li>\n<li><em>Foundation FCs</em> linken typischerweise als Shared- oder Static-Libraries direkt in den Kontext der AA ein (<code>ara::*</code>-Header/Libraries) und kommunizieren über Systemaufrufe direkt mit dem Kernel oder über IPC mit Background-Daemons.</li>\n<li><em>Platform Services</em> laufen als eigenständige Daemons und werden von AAs transparent über generierte Proxy-/Skeleton-Klassen via <code>ara::com</code> konsumiert.</li>\n<li><strong>Abstraktion:</strong> Für die AA ist die Interaktionsform mit Plattform-Services und Non-Platform-Services identisch (strikte C++14/C++17-Interface-Semantik).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Das Diagramm ist ein statisches Strukturmodell; aus den architekturellen Abhängigkeiten ergeben sich jedoch fundamentale dynamische Interaktionspfade:</em></p>\n<ol class=\"fig-list\">\n<li><strong>Bootstrap & Prozessstart:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Plattform-Boot $\\rightarrow$ OS initialisiert Hardware/Treiber.</li>\n<li><code>ara::exec</code> (Execution Management) startet als Init-Prozess/Master-Daemon und fährt Funktionsgruppen (Function Groups) gemäß Manifest hoch.</li>\n<li><code>ara::exec</code> spawnt AAs als native POSIX-Prozesse und setzt Capabilities/POSIX-Resource-Limits.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Service Discovery & Binding (<code>ara::com</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Service-Provider (<code>ASW::XYZ</code> oder Platform Services wie <code>ara::ucm</code>) initialisieren ein Skeleton und rufen <code>OfferService()</code> auf.</li>\n<li>Service-Consumer initialisieren einen Proxy, triggern <code>FindService()</code> (asynchron via Handler oder synchron polling) und binden nach Discovery an die Instanz.</li>\n<li>Nachrichtenfluss erfolgt wahlweise per Shared Memory/Unix Domain Socket (<em>IPC</em> lokal) oder Ethernet (<em>SOME/IP</em>, <em>DDS</em> extern/intra-ECU).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Supervision & Health Management:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>AA meldet zyklisch Checkpoints über <code>ara::phm</code>-Client-APIs (<code>ReportCheckpoint()</code>).</li>\n<li>PhM aggregiert Status gegen definierte Transitionsregeln; bei Verletzung (Deadline/Alive) Trigger an <code>ara::sm</code> zur Recovery-Einleitung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Schnittstellenvertrag:</strong></li>\n<li>Applikationscode darf <strong>ausschließlich</strong> auf spezifizierte ARA-Schnittstellen (<code>ara::<em></code>), POSIX PSE51 und C++ STL zugreifen. Direkte Treiber-Zugriffe (z. B. Kernel-Module, <code>/dev/</em></code>) oder proprietäre IPC-Mechanismen verletzen die Konformität und Portabilität.</li>\n<li>Ausnahmslose Verwendung von <code>ara::core::Result&lt;T, E&gt;</code> / <code>ara::core::ErrorCode</code> anstelle von C++-Exceptions in sicherheitskritischen Bereichen (ASIL-Kontext).</li>\n<li><strong>Konfigurations- und Bereitstellungs-Einschränkungen (Manifests):</strong></li>\n<li>Jede Interaktion erfordert AUTOSAR-Manifest-Modelle (ARXML): <em>Execution Manifest</em> (für <code>ara::exec</code>), <em>Service Instance Manifest</em> (für <code>ara::com</code>, Protokollbindung SOME/IP/IPC) und <em>Service Interface Deployment</em>.</li>\n<li>IAM-Policies müssen explizit konfiguriert werden; unautorisierte Zugriffe einer AA auf <code>ara::*</code>-APIs werden zur Laufzeit durch <code>ara::iam</code> blockiert.</li>\n<li><strong>Architekturelle Restriktionen:</strong></li>\n<li>Das Schaubild visualisiert logische Cluster, keine physischen Prozessgrenzen: Ein Foundation FC kann aus einer Client-Bibliothek plus einem dedizierten Hintergrund-Daemon bestehen.</li>\n<li>Nicht alle dargestellten Functional Clusters müssen im konkreten AP-Stack-Release oder Ziel-Image instanziiert sein (Konfigurationsabhängigkeit laut Spezifikationshinweis zu R21-11).</li>\n</ul>"}, {"id": "FIG-b0aba348c91ecff8", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (Blockarchitektur) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung der statischen Dekomposition der AP-Laufzeitumgebung (ARA) und deren Abgrenzung gegenüber Applikationsebene (User Applications), Betriebssystemebene (OSI-Schicht via POSIX) und unterlagerter Ausführungsumgebung (Hardware/VM/Container).</li>\n<li><strong>Systemische Einordnung:</strong> Definiert die logische Struktur eines AP-Knotens gemäß AUTOSAR R21-11 (<code>AUTOSAR_EXP_PlatformDesign</code>). Veranschaulicht das Dualitätsprinzip zwischen <em>Platform Foundation Functional Clusters</em> (bibliotheksbasierte In-Process-APIs) und <em>Platform Service Functional Clusters</em> (serviceorientierte IPC/Netzwerk-Dienste), die für Adaptive Applications (AA) über eine einheitliche C++-API abstrahiert werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Entitäten (Top-to-Bottom)</p>\n<ul class=\"fig-list\">\n<li><strong>User Applications:</strong></li>\n<li><strong>Adaptive Application (AA):</strong> POSIX-konforme Nutzerprozesse mit eigenem virtuellem Adressraum.</li>\n<li><strong>Non-PF Service (<code>ASW::XYZ</code>, <code>ASW::ABC</code>):</strong> Anwendungsdienste, die über das Service-Interface von <code>ara::com</code> für andere AAs bereitgestellt werden.</li>\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong></li>\n<li><strong>Platform Foundation Functional Clusters (API-orientiert, blau kodiert):</strong></li>\n<li><code>ara::core</code>: Basistypen, Core-Fehlerbehandlung, Speicher- und Initialisierungsmechanismen.</li>\n<li><code>ara::com</code>: Service-Oriented Communication (SOC) mit Transportbindungen an IPC, Signal PDU, SOME/IP und DDS.</li>\n<li><code>ara::exec</code>: Prozesslebenszyklus, Scheduling und Deterministic Client Control.</li>\n<li><code>ara::iam</code>: Autorisierung und Zugriffskontrolle.</li>\n<li><code>ara::crypto</code>: PKI, Schlüsselverwaltung, kryptografische Operationen.</li>\n<li><code>ara::per</code>: Persistente Speicherung (Key-Value- und File-Storage).</li>\n<li><code>ara::phm</code>: Alive-, Deadline- und Logical-Supervision von AAs.</li>\n<li><code>ara::log</code>: Strukturiertes Logging und Tracing (DLT).</li>\n<li><code>ara::idsm</code>: Erfassung und Weiterleitung von Security-Events.</li>\n<li><code>ara::tsync</code>: Hochgenaue Zeitsynchronisation (PTP / IEEE 802.1AS).</li>\n<li><code>ara::diag</code>: Fahrzeugdiagnose über UDS / DoIP.</li>\n<li><code>ara::fw</code>: Firewall zur Paketfilterung, Netzwerkverkehrsüberwachung und Regelprüfung (neu platziert neben dem OS-Interface).</li>\n<li><strong>Platform Service Functional Clusters (Service-orientiert, grau kodiert):</strong></li>\n<li><code>ara::sm service</code>: Zustands- und Funktionsgruppenmanagement (State Management).</li>\n<li><code>ara::ucm service</code>: Update and Config Management (Software-Aktualisierung / OTA).</li>\n<li><code>ara::nm service</code>: Netzwerk-Management (Bus-Schlaf-/Wachzustände).</li>\n<li><strong>Operating System Interface:</strong></li>\n<li>Standardisiertes Subsystem via <strong>POSIX PSE51</strong> und <strong>C++ STL</strong>; im rechten Bereich baulich verkürzt zur Aufnahme des Blocks <code>ara::fw</code>.</li>\n<li><strong>Unterlagerte Basis:</strong></li>\n<li><code>(Virtual) Machine / Container / Hardware</code>: Abstraktion über Hypervisor-Partitionen, Linux-Namespaces/Container oder Bare-Metal-Hardware-Ressourcen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Das Diagramm ist ein statisches Strukturmodell; aus den architekturellen Abhängigkeiten ergeben sich jedoch fundamentale dynamische Interaktionspfade:</em></p>\n<ol class=\"fig-list\">\n<li><strong>Bootstrap & Prozessstart:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Plattform-Boot $\\rightarrow$ OS initialisiert Hardware/Treiber.</li>\n<li><code>ara::exec</code> (Execution Management) startet als Init-Prozess/Master-Daemon und fährt Funktionsgruppen (Function Groups) gemäß Manifest hoch.</li>\n<li><code>ara::exec</code> spawnt AAs als native POSIX-Prozesse und setzt Capabilities/POSIX-Resource-Limits.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Service Discovery & Binding (<code>ara::com</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Service-Provider (<code>ASW::XYZ</code> oder Platform Services wie <code>ara::ucm</code>) initialisieren ein Skeleton und rufen <code>OfferService()</code> auf.</li>\n<li>Service-Consumer initialisieren einen Proxy, triggern <code>FindService()</code> (asynchron via Handler oder synchron polling) und binden nach Discovery an die Instanz.</li>\n<li>Nachrichtenfluss erfolgt wahlweise per Shared Memory/Unix Domain Socket (<em>IPC</em> lokal) oder Ethernet (<em>SOME/IP</em>, <em>DDS</em> extern/intra-ECU).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Supervision & Health Management:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>AA meldet zyklisch Checkpoints über <code>ara::phm</code>-Client-APIs (<code>ReportCheckpoint()</code>).</li>\n<li>PhM aggregiert Status gegen definierte Transitionsregeln; bei Verletzung (Deadline/Alive) Trigger an <code>ara::sm</code> zur Recovery-Einleitung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Schnittstellenvertrag:</strong></li>\n<li>Applikationscode darf <strong>ausschließlich</strong> auf spezifizierte ARA-Schnittstellen (<code>ara::<em></code>), POSIX PSE51 und C++ STL zugreifen. Direkte Treiber-Zugriffe (z. B. Kernel-Module, <code>/dev/</em></code>) oder proprietäre IPC-Mechanismen verletzen die Konformität und Portabilität.</li>\n<li>Ausnahmslose Verwendung von <code>ara::core::Result&lt;T, E&gt;</code> / <code>ara::core::ErrorCode</code> anstelle von C++-Exceptions in sicherheitskritischen Bereichen (ASIL-Kontext).</li>\n<li><strong>Konfigurations- und Bereitstellungs-Einschränkungen (Manifests):</strong></li>\n<li>Jede Interaktion erfordert AUTOSAR-Manifest-Modelle (ARXML): <em>Execution Manifest</em> (für <code>ara::exec</code>), <em>Service Instance Manifest</em> (für <code>ara::com</code>, Protokollbindung SOME/IP/IPC) und <em>Service Interface Deployment</em>.</li>\n<li>IAM-Policies müssen explizit konfiguriert werden; unautorisierte Zugriffe einer AA auf <code>ara::*</code>-APIs werden zur Laufzeit durch <code>ara::iam</code> blockiert.</li>\n<li><strong>Architekturelle Restriktionen:</strong></li>\n<li>Das Schaubild visualisiert logische Cluster, keine physischen Prozessgrenzen: Ein Foundation FC kann aus einer Client-Bibliothek plus einem dedizierten Hintergrund-Daemon bestehen.</li>\n<li>Nicht alle dargestellten Functional Clusters müssen im konkreten AP-Stack-Release oder Ziel-Image instanziiert sein (Konfigurationsabhängigkeit laut Spezifikationshinweis zu R21-11).</li>\n</ul>"}, {"id": "FIG-8e4b6f7e8b95f1ec", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Schichten- und Säulenmodell (Blockarchitektur) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck:</strong> Statische Dekomposition der AP-Laufzeitumgebung (ARA) in vier funktionale Cluster-Domänen mit vertikaler OS-Schnittstellenabstraktion und Abgrenzung gegenüber Applikationsebene (User Application) und Basisbetriebssystem (Base Software / POSIX OS).</li>\n<li><strong>Systemische Einordnung:</strong> Definiert die logische Plattformarchitektur gemäß AUTOSAR R23-11 (<code>AUTOSAR_EXP_PlatformDesign</code>). Führt eine viergliedrige Cluster-Taxonomie ein (Platform Foundation FCs, Platform Service FCs, Standardized App/Interface FCs, Vehicle Service FCs) und entkoppelt das POSIX OS als eigenständige Base Software von der ARA.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>User Application:</strong></li>\n<li><strong>Application:</strong> Generalisierte Applikationsschicht, die funktionale Softwarekomponenten und fahrzeugbezogene Benutzeranwendungen zusammenfasst.</li>\n<li><strong>AUTOSAR Runtime for Adaptive applications - ARA:</strong></li>\n<li><strong>Operating System Interface (vertikale Randschicht):</strong></li>\n<li><code>POSIX PSE51 / C++ STL Operating System Interface</code>: Standardisierte Schnittstelle zu Threads, Speicher und Dateisystem, die allen Funktionsclustern innerhalb der ARA vertikal zur Verfügung steht.</li>\n<li><strong>Platform Foundation Functional Clusters (FCs) (blau kodiert, API-orientiert):</strong></li>\n<li><code>ara::com</code> (Communication Management): Service-Oriented Communication (SOC).</li>\n<li><code>ara::exec</code> (Execution Management): Prozesslebenszyklus, Scheduling und Zustandswechsel.</li>\n<li><code>ara::diag</code> (Diagnostic Management): UDS- und DoIP-basierte Diagnoseverarbeitung.</li>\n<li><code>ara::idsm</code> (Intrusion Detection System Manager): Erfassung von Security-Events.</li>\n<li><code>ara::nm</code> (Network Management): Zustandsmanagement von Netzwerk-Clustern (in Foundation überführt).</li>\n<li><code>ara::per</code> (Persistency): Schlüssel-Wert- und dateibasierte Datenspeicherung.</li>\n<li><code>ara::tsync</code> (Time Synchronization): Hochpräzise Uhrensynchronisation (IEEE 802.1AS).</li>\n<li><code>ara::crypto</code> (Cryptography): Kryptografische Algorithmen und Schlüsselmanagement.</li>\n<li><code>ara::rds</code> (Raw Data Stream): Streaming unstrukturierter oder echtzeitkritischer Rohdaten (z. B. Sensor-/Videoströme).</li>\n<li><code>ara::phm</code> (Platform Health Management): Überwachung von Alive-, Deadline- und logischen Abläufen.</li>\n<li><code>ara::log</code> (Log and Trace): Systemweites DLT-Logging.</li>\n<li><code>ara::fw</code> (Firewall): Paket- und Kommunikationsfilterung auf Netzwerkebene.</li>\n<li><code>ara::core</code> (Core): Basistypen, Result/ErrorCode-Fehlerbehandlung und Speicherinitialisierung.</li>\n<li><strong>Platform Service FCs (grau kodiert, plattformlokale Dienste):</strong></li>\n<li><code>ara::ucm service</code> (Update and Config Management): Softwarepaket- und Konfigurationsaktualisierung.</li>\n<li><code>ara::sm service</code> (State Management): Systemzustands- und Funktionsgruppensteuerung.</li>\n<li><strong>Standardized App/Interface FCs (orange kodiert, standardisierte Fachdomänen-Schnittstellen):</strong></li>\n<li><code>ara:adi::sensoritf service</code> (Sensor Interfaces): Standardisierte Schnittstelle zur Anbindung von Sensoren und ADAS/Sensor-Frameworks.</li>\n<li><strong>Vehicle Service FCs (grün kodiert, fahrzeugweite Dienste):</strong></li>\n<li><code>ara::vucm service</code> (Vehicle Update and Config Management): Flotten- und fahrzeugweites Update- und Konfigurationsmanagement über mehrere Knoten hinweg.</li>\n<li><strong>Base Software:</strong></li>\n<li><code>POSIX OS</code>: Unterlagertes POSIX-konformes Betriebssystem zur Bereitstellung von Prozessisolation und Hardwaretreibern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Schichten- und domänenübergreifende Interaktion:</strong></li>\n<li>Applikationen greifen über zwei distinkte Pfade auf Plattformfunktionen zu:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Direkte In-Process-Aufrufe über statisch/dynamisch gelinkte C++-APIs in die Platform Foundation FCs (<code>ara::core</code>, <code>ara::per</code>, <code>ara::crypto</code>, <code>ara::rds</code> etc.).</li>\n<li>Serviceorientierte Aufrufe über <code>ara::com</code> zur Nutzung von Diensten der Platform Service FCs (<code>ara::sm</code>, <code>ara::ucm</code>), der Standardized App/Interface FCs (<code>ara:adi::sensoritf</code>) sowie der Vehicle Service FCs (<code>ara::vucm</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>ara::rds</code> ermöglicht direkte Datentransportpfade für kontinuierliche Sensordatenströme unter Umgehung des klassischen RPC/Event-Overheads von <code>ara::com</code>.</li>\n<li><strong>Prozess- und Systemkopplung:</strong></li>\n<li>Der Zugriff auf OS-Primitive (Threads, Mutexes, POSIX-Sockets) erfolgt durch alle ARA-Cluster konsistent über die linksseitig visualisierte Abstraktionsschicht <code>POSIX PSE51 / C++ STL</code>.</li>\n<li><code>POSIX OS</code> bildet als Teil der <code>Base Software</code> die unterlagerte Ausführungsumgebung, getrennt von der logischen ARA-Definition.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Taxonomie & Standardisierungsgrenzen:</strong></li>\n<li>Die Aufteilung in vier Cluster-Familien definiert unterschiedliche Verantwortungsbereiche: Foundation (knotenlokale Basisbibliotheken), Platform Services (knotenlokale Systemdaemons), Standardized App/Interface (domänenspezifische Sensorabstraktionen) und Vehicle Services (netzwerkweite Gesamtfahrzeug-Dienste).</li>\n<li>Durch die Einführung von <code>ara::rds</code> wird die strikte Beschränkung auf <code>ara::com</code> für Hochdurchsatz-Sensordaten gelockert.</li>\n<li>Der Wegfall von <code>ara::iam</code> verdeutlicht die Konsolidierung von Authentifizierungs- und Autorisierungsmechanismen auf OS- und Core-Ebene.</li>\n<li><strong>Integrationsrichtlinien:</strong></li>\n<li>Die vertikale Auslassungssymbolik (<code>⋮</code>) in allen vier Säulen kennzeichnet offene Erweiterungspunkte für künftige Funktionscluster.</li>\n<li>Applikationen dürfen keine Annahmen über proprietäre POSIX-Erweiterungen treffen; die Portabilität stützt sich strikt auf das PSE51-Profil und C++ STL.</li>\n</ul>"}, {"id": "FIG-2f77eda5f6ed03a6", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Schichten- und Säulenmodell (Blockarchitektur) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck:</strong> Statische Dekomposition der AP-Laufzeitumgebung (ARA) in vier funktionale Cluster-Domänen mit vertikaler OS-Schnittstellenabstraktion und Abgrenzung gegenüber Applikationsebene (User Application) und Basisbetriebssystem (Base Software / POSIX OS).</li>\n<li><strong>Systemische Einordnung:</strong> Definiert die logische Plattformarchitektur gemäß AUTOSAR R23-11 (<code>AUTOSAR_EXP_PlatformDesign</code>). Führt eine viergliedrige Cluster-Taxonomie ein (Platform Foundation FCs, Platform Service FCs, Standardized App/Interface FCs, Vehicle Service FCs) und entkoppelt das POSIX OS als eigenständige Base Software von der ARA.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>User Application:</strong></li>\n<li><strong>Application:</strong> Generalisierte Applikationsschicht, die funktionale Softwarekomponenten und fahrzeugbezogene Benutzeranwendungen zusammenfasst.</li>\n<li><strong>AUTOSAR Runtime for Adaptive applications - ARA:</strong></li>\n<li><strong>Operating System Interface (vertikale Randschicht):</strong></li>\n<li><code>POSIX PSE51 / C++ STL Operating System Interface</code>: Standardisierte Schnittstelle zu Threads, Speicher und Dateisystem, die allen Funktionsclustern innerhalb der ARA vertikal zur Verfügung steht.</li>\n<li><strong>Platform Foundation Functional Clusters (FCs) (blau kodiert, API-orientiert):</strong></li>\n<li><code>ara::com</code> (Communication Management): Service-Oriented Communication (SOC).</li>\n<li><code>ara::exec</code> (Execution Management): Prozesslebenszyklus, Scheduling und Zustandswechsel.</li>\n<li><code>ara::diag</code> (Diagnostic Management): UDS- und DoIP-basierte Diagnoseverarbeitung.</li>\n<li><code>ara::idsm</code> (Intrusion Detection System Manager): Erfassung von Security-Events.</li>\n<li><code>ara::nm</code> (Network Management): Zustandsmanagement von Netzwerk-Clustern.</li>\n<li><code>ara::per</code> (Persistency): Schlüssel-Wert- und dateibasierte Datenspeicherung.</li>\n<li><code>ara::tsync</code> (Time Synchronization): Hochpräzise Uhrensynchronisation (IEEE 802.1AS).</li>\n<li><code>ara::crypto</code> (Cryptography): Kryptografische Algorithmen und Schlüsselmanagement.</li>\n<li><code>ara::rds</code> (Raw Data Stream): Streaming unstrukturierter oder echtzeitkritischer Rohdaten.</li>\n<li><code>ara::phm</code> (Platform Health Management): Überwachung von Alive-, Deadline- und logischen Abläufen.</li>\n<li><code>ara::log</code> (Log and Trace): Systemweites DLT-Logging.</li>\n<li><code>ara::fw</code> (Firewall): Paket- und Kommunikationsfilterung auf Netzwerkebene.</li>\n<li><code>ara::core</code> (Core): Basistypen, Result/ErrorCode-Fehlerbehandlung und Speicherinitialisierung.</li>\n<li><strong>Platform Service FCs (grau kodiert, plattformlokale Dienste):</strong></li>\n<li><code>ara::ucm service</code> (Update and Config Management): Softwarepaket- und Konfigurationsaktualisierung.</li>\n<li><code>ara::sm service</code> (State Management): Systemzustands- und Funktionsgruppensteuerung.</li>\n<li><strong>Standardized App/Interface FCs (orange kodiert, standardisierte Fachdomänen-Schnittstellen):</strong></li>\n<li><code>ara:adi::sensoritf service</code> (Sensor Interfaces): Standardisierte Schnittstelle zur Anbindung von Sensoren und ADAS/Sensor-Frameworks.</li>\n<li><strong>Vehicle Service FCs (grün kodiert, fahrzeugweite Dienste):</strong></li>\n<li><code>ara::vucm service</code> (Vehicle Update and Config Management): Flotten- und fahrzeugweites Update- und Konfigurationsmanagement.</li>\n<li><code>ara::aag</code> (Automotive API Gateway): Gateway-Service zur standardisierten Bereitstellung und Übersetzung von Fahrzeug-APIs gegenüber externen oder fahrzeugweiten Domänen.</li>\n<li><strong>Base Software:</strong></li>\n<li><code>POSIX OS</code>: Unterlagertes POSIX-konformes Betriebssystem zur Bereitstellung von Prozessisolation und Hardwaretreibern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Schichten- und domänenübergreifende Interaktion:</strong></li>\n<li>Applikationen greifen über zwei distinkte Pfade auf Plattformfunktionen zu:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Direkte In-Process-Aufrufe über statisch/dynamisch gelinkte C++-APIs in die Platform Foundation FCs (<code>ara::core</code>, <code>ara::per</code>, <code>ara::crypto</code>, <code>ara::rds</code> etc.).</li>\n<li>Serviceorientierte Aufrufe über <code>ara::com</code> zur Nutzung von Diensten der Platform Service FCs (<code>ara::sm</code>, <code>ara::ucm</code>), der Standardized App/Interface FCs (<code>ara:adi::sensoritf</code>) sowie der Vehicle Service FCs (<code>ara::vucm</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>ara::rds</code> ermöglicht direkte Datentransportpfade für kontinuierliche Sensordatenströme unter Umgehung des klassischen RPC/Event-Overheads von <code>ara::com</code>.</li>\n<li><strong>Prozess- und Systemkopplung:</strong></li>\n<li>Der Zugriff auf OS-Primitive (Threads, Mutexes, POSIX-Sockets) erfolgt durch alle ARA-Cluster konsistent über die linksseitig visualisierte Abstraktionsschicht <code>POSIX PSE51 / C++ STL</code>.</li>\n<li><code>POSIX OS</code> bildet als Teil der <code>Base Software</code> die unterlagerte Ausführungsumgebung, getrennt von der logischen ARA-Definition.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Taxonomie & Standardisierungsgrenzen:</strong></li>\n<li>Die Aufteilung in vier Cluster-Familien definiert unterschiedliche Verantwortungsbereiche: Foundation (knotenlokale Basisbibliotheken), Platform Services (knotenlokale Systemdaemons), Standardized App/Interface (domänenspezifische Sensorabstraktionen) und Vehicle Services (netzwerkweite Gesamtfahrzeug-Dienste).</li>\n<li>Durch die Einführung von <code>ara::rds</code> wird die strikte Beschränkung auf <code>ara::com</code> für Hochdurchsatz-Sensordaten gelockert.</li>\n<li>Der Wegfall von <code>ara::iam</code> verdeutlicht die Konsolidierung von Authentifizierungs- und Autorisierungsmechanismen auf OS- und Core-Ebene.</li>\n<li><strong>Integrationsrichtlinien:</strong></li>\n<li>Die vertikale Auslassungssymbolik (<code>⋮</code>) in allen vier Säulen kennzeichnet offene Erweiterungspunkte für künftige Funktionscluster.</li>\n<li>Applikationen dürfen keine Annahmen über proprietäre POSIX-Erweiterungen treffen; die Portabilität stützt sich strikt auf das PSE51-Profil und C++ STL.</li>\n</ul>"}, {"id": "FIG-43c51c0572bbee89", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Logisches Schichten- und Säulenmodell (Blockarchitektur) der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Technischer Zweck:</strong> Statische Dekomposition der AP-Laufzeitumgebung (ARA) in vier funktionale Cluster-Domänen mit vertikaler OS-Schnittstellenabstraktion und Abgrenzung gegenüber Applikationsebene (User Application) und Basisbetriebssystem (Base Software / POSIX OS).</li>\n<li><strong>Systemische Einordnung:</strong> Definiert die logische Plattformarchitektur gemäß AUTOSAR R23-11 (<code>AUTOSAR_EXP_PlatformDesign</code>). Führt eine viergliedrige Cluster-Taxonomie ein (Platform Foundation FCs, Platform Service FCs, Standardized App/Interface FCs, Vehicle Service FCs) und entkoppelt das POSIX OS als eigenständige Base Software von der ARA.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>User Application:</strong></li>\n<li><strong>Application:</strong> Generalisierte Applikationsschicht, die funktionale Softwarekomponenten und fahrzeugbezogene Benutzeranwendungen zusammenfasst.</li>\n<li><strong>AUTOSAR Runtime for Adaptive applications - ARA:</strong></li>\n<li><strong>Operating System Interface (vertikale Randschicht):</strong></li>\n<li><code>POSIX PSE51 / C++ STL Operating System Interface</code>: Standardisierte Schnittstelle zu Threads, Speicher und Dateisystem, die allen Funktionsclustern innerhalb der ARA vertikal zur Verfügung steht.</li>\n<li><strong>Platform Foundation Functional Clusters (FCs) (blau kodiert, API-orientiert):</strong></li>\n<li><code>ara::com</code> (Communication Management): Service-Oriented Communication (SOC).</li>\n<li><code>ara::exec</code> (Execution Management): Prozesslebenszyklus, Scheduling und Zustandswechsel.</li>\n<li><code>ara::diag</code> (Diagnostic Management): UDS- und DoIP-basierte Diagnoseverarbeitung.</li>\n<li><code>ara::idsm</code> (Intrusion Detection System Manager): Erfassung von Security-Events.</li>\n<li><code>ara::nm</code> (Network Management): Zustandsmanagement von Netzwerk-Clustern.</li>\n<li><code>ara::per</code> (Persistency): Schlüssel-Wert- und dateibasierte Datenspeicherung.</li>\n<li><code>ara::tsync</code> (Time Synchronization): Hochpräzise Uhrensynchronisation (IEEE 802.1AS).</li>\n<li><code>ara::crypto</code> (Cryptography): Kryptografische Algorithmen und Schlüsselmanagement.</li>\n<li><code>ara::rds</code> (Raw Data Stream): Streaming unstrukturierter oder echtzeitkritischer Rohdaten.</li>\n<li><code>ara::phm</code> (Platform Health Management): Überwachung von Alive-, Deadline- und logischen Abläufen.</li>\n<li><code>ara::log</code> (Log and Trace): Systemweites DLT-Logging.</li>\n<li><code>ara::shwa</code> (Safe Hardware Acceleration): Standardisierte Schnittstelle für sichere und deterministische Hardwarebeschleunigung (z. B. GPUs, NPUs, FPGAs).</li>\n<li><code>ara::fw</code> (Firewall): Paket- und Kommunikationsfilterung auf Netzwerkebene.</li>\n<li><code>ara::core</code> (Core): Basistypen, Result/ErrorCode-Fehlerbehandlung und Speicherinitialisierung.</li>\n<li><strong>Platform Service FCs (grau kodiert, plattformlokale Dienste):</strong></li>\n<li><code>ara::ucm service</code> (Update and Config Management): Softwarepaket- und Konfigurationsaktualisierung.</li>\n<li><code>ara::sm service</code> (State Management): Systemzustands- und Funktionsgruppensteuerung.</li>\n<li><strong>Standardized App/Interface FCs (orange kodiert, standardisierte Fachdomänen-Schnittstellen):</strong></li>\n<li><code>ara:adi::sensoritf service</code> (Sensor Interfaces): Standardisierte Schnittstelle zur Anbindung von Sensoren und ADAS/Sensor-Frameworks.</li>\n<li><strong>Vehicle Service FCs (grün kodiert, fahrzeugweite Dienste):</strong></li>\n<li><code>ara::vucm service</code> (Vehicle Update and Config Management): Flotten- und fahrzeugweites Update- und Konfigurationsmanagement.</li>\n<li><code>ara::aag</code> (Automotive API Gateway): Gateway-Service zur standardisierten Bereitstellung und Übersetzung von Fahrzeug-APIs.</li>\n<li><code>ara::rper service</code> (Remote Persistency): Service für persistente Datenspeicherung auf entfernten Knoten oder im Gesamtfahrzeugnetzwerk.</li>\n<li><strong>Base Software:</strong></li>\n<li><code>POSIX OS</code>: Unterlagertes POSIX-konformes Betriebssystem zur Bereitstellung von Prozessisolation und Hardwaretreibern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Schichten- und domänenübergreifende Interaktion:</strong></li>\n<li>Applikationen greifen über zwei distinkte Pfade auf Plattformfunktionen zu:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Direkte In-Process-Aufrufe über statisch/dynamisch gelinkte C++-APIs in die Platform Foundation FCs (<code>ara::core</code>, <code>ara::per</code>, <code>ara::crypto</code>, <code>ara::rds</code> etc.).</li>\n<li>Serviceorientierte Aufrufe über <code>ara::com</code> zur Nutzung von Diensten der Platform Service FCs (<code>ara::sm</code>, <code>ara::ucm</code>), der Standardized App/Interface FCs (<code>ara:adi::sensoritf</code>) sowie der Vehicle Service FCs (<code>ara::vucm</code>).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>ara::rds</code> ermöglicht direkte Datentransportpfade für kontinuierliche Sensordatenströme unter Umgehung des klassischen RPC/Event-Overheads von <code>ara::com</code>.</li>\n<li><strong>Prozess- und Systemkopplung:</strong></li>\n<li>Der Zugriff auf OS-Primitive (Threads, Mutexes, POSIX-Sockets) erfolgt durch alle ARA-Cluster konsistent über die linksseitig visualisierte Abstraktionsschicht <code>POSIX PSE51 / C++ STL</code>.</li>\n<li><code>POSIX OS</code> bildet als Teil der <code>Base Software</code> die unterlagerte Ausführungsumgebung, getrennt von der logischen ARA-Definition.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Taxonomie & Standardisierungsgrenzen:</strong></li>\n<li>Die Aufteilung in vier Cluster-Familien definiert unterschiedliche Verantwortungsbereiche: Foundation (knotenlokale Basisbibliotheken), Platform Services (knotenlokale Systemdaemons), Standardized App/Interface (domänenspezifische Sensorabstraktionen) und Vehicle Services (netzwerkweite Gesamtfahrzeug-Dienste).</li>\n<li>Durch die Einführung von <code>ara::rds</code> wird die strikte Beschränkung auf <code>ara::com</code> für Hochdurchsatz-Sensordaten gelockert.</li>\n<li>Der Wegfall von <code>ara::iam</code> verdeutlicht die Konsolidierung von Authentifizierungs- und Autorisierungsmechanismen auf OS- und Core-Ebene.</li>\n<li><strong>Integrationsrichtlinien:</strong></li>\n<li>Die vertikale Auslassungssymbolik (<code>⋮</code>) in allen vier Säulen kennzeichnet offene Erweiterungspunkte für künftige Funktionscluster.</li>\n<li>Applikationen dürfen keine Annahmen über proprietäre POSIX-Erweiterungen treffen; die Portabilität stützt sich strikt auf das PSE51-Profil und C++ STL.</li>\n</ul>"}], "trans": [{"from": "FIG-7f3120f846dbdedb", "to": "FIG-b0aba348c91ecff8", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong><code>ara::fw</code> (Firewall):</strong> Neuer Functional Cluster im ARA-Bereich unterhalb von <code>ara::nm service</code> ergänzt.</li>\n<li><strong>Operating System Interface (<code>POSIX PSE51 / C++ STL</code>):</strong> Blockbreite nach rechts verkürzt, um Platz für den neuen Baustein <code>ara::fw</code> freizugeben.</li>\n</ul>"}, {"from": "FIG-b0aba348c91ecff8", "to": "FIG-8e4b6f7e8b95f1ec", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Cluster-Kategorisierung:</strong> Einführung von vier getrennten Cluster-Kategorien innerhalb von ARA: <em>Platform Foundation Functional Clusters (FCs)</em>, <em>Platform Service FCs</em>, <em>Standardized App/Interface FCs</em> (neu) und <em>Vehicle Service FCs</em> (neu).</li>\n<li><strong>Standardized App/Interface FCs:</strong> Neue Kategorie mit <code>Sensor Interfaces</code> (<code>ara:adi::sensoritf service</code>).</li>\n<li><strong>Vehicle Service FCs:</strong> Neue fahrzeugweite Service-Kategorie mit <code>Vehicle Update and Config Management</code> (<code>ara::vucm service</code>).</li>\n<li><strong><code>ara::rds</code> (Raw Data Stream):</strong> Neuer Functional Cluster in den Platform Foundation FCs ergänzt.</li>\n<li><strong><code>ara::nm</code> (Network Management):</strong> Von Platform Service FCs (<code>ara::nm service</code>) zu den Platform Foundation FCs (<code>ara::nm</code>) verschoben.</li>\n<li><strong><code>ara::fw</code> (Firewall):</strong> Als regulärer Platform Foundation FC eingegliedert.</li>\n<li><strong><code>ara::iam</code> (Identity and Access Management):</strong> Aus den Platform Foundation FCs entfernt.</li>\n<li><strong><code>ara::diag</code>:</strong> Umbenannt von „Diagnostics“ in „Diagnostic Management“.</li>\n<li><strong><code>ara::com</code>:</strong> Transportprotokoll-Subblöcke (<em>IPC</em>, <em>Signal PDU</em>, <em>SOME/IP</em>, <em>DDS</em>) aus dem Schaubild entfernt.</li>\n<li><strong>User Application:</strong> Konsolidierung der Einzelfelder (<em>Adaptive Application</em>, <em>Non-PF Service</em>) zu einem einheitlichen horizontalen Block „Application“.</li>\n<li><strong>Operating System Interface:</strong> Von horizontalem Fußbalken zu einer vertikalen Säule am linken Rand der ARA umpositioniert.</li>\n<li><strong>Base Software:</strong> Die unterlagerte Ebene wurde von „(Virtual) Machine / Container / Hardware“ zu „Base Software“ mit Sub-Block „POSIX OS“ restrukturiert.</li>\n<li><strong>Legende:</strong> Die separate „Key“-Box am rechten Rand wurde entfernt.</li>\n<li><strong>Erweiterbarkeit:</strong> Aufnahme vertikaler Auslassungspunkte (<code>⋮</code>) in allen vier Cluster-Kategorien zur Kennzeichnung zukünftiger FCs.</li>\n</ul>"}, {"from": "FIG-8e4b6f7e8b95f1ec", "to": "FIG-2f77eda5f6ed03a6", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong><code>ara::aag</code> (Automotive API Gateway):</strong> Neuer Functional Cluster in der Kategorie <em>Vehicle Service FCs</em> in Zeile 2 ergänzt.</li>\n</ul>"}, {"from": "FIG-2f77eda5f6ed03a6", "to": "FIG-43c51c0572bbee89", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong><code>ara::shwa</code> (Safe Hardware Acceleration):</strong> Neuer Functional Cluster in der Kategorie <em>Platform Foundation Functional Clusters (FCs)</em> in Zeile 3, Spalte 4 ergänzt.</li>\n<li><strong><code>ara::rper service</code> (Remote Persistency):</strong> Neuer Functional Cluster in der Kategorie <em>Vehicle Service FCs</em> in Zeile 3 ergänzt.</li>\n</ul>"}]};
